            .await?;
        let ((arguments, target), inner) = match gate {
            Gate::Stop(stopped) => return Ok(stopped),
            Gate::Open { parts, inner } => (parts, inner),
        };
        let labels = if target.labeled_element_declarations.is_empty() {
            None
